-- --------------------------------------------------------------------------
-- Person (bus_person)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f261c5c1-cf8d-59e8-9bb2-f6e6ff187e4c', 'Person', 'Maintain Person records', 'Create, find and maintain Person records. The list shows every Person you have access to — select a row to open it, or use New to add one. Each row is a single Person, described by 14 fields.

Id and Party are unique: no two Person records may share the same value, and a save that would duplicate one is rejected. Party, Given Name, Family Name, Party Type, Display Name and Status must be filled in before the record can be saved.

Every Person points at Party. Choose the linked record from the lookup on those fields rather than typing an identifier. Organization, Party Role and Address refer back to Person, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Person then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Person with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d72ecd5-1038-5d1c-b88c-982195987d5a', 'bus_person', 'Person', 'Person is the individual specialization of Party, not a business role. Party identifies the individual; Person supplies intrinsic individual details; PartyRole determines how the person participates. Used for customers, employees, agents, owners, contractors, and other roles without duplicating individual identity. Party → Person establishes intrinsic identity; Party → PartyRole establishes business participation; Organization links provide employment or other organizational context. Create/maintain Party → create Person specialization → establish PartyRole → apply role-specific qualification/authorization → execute transactions. Ending one role does not end the person or other roles. Person specialization follows Party identity while role eligibility remains independently controlled by PartyRole. One individual may be both an Employee and Customer. The same Party and Person specialization is reused while separate PartyRoles govern employment and customer processes.', 'A', FALSE, FALSE, FALSE, TRUE, 'f261c5c1-cf8d-59e8-9bb2-f6e6ff187e4c', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a4bd0d2e-ec8e-558c-aedd-762fcf1af362', 'f261c5c1-cf8d-59e8-9bb2-f6e6ff187e4c', '4d72ecd5-1038-5d1c-b88c-982195987d5a', 'Person', 'Shows one Person at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Party is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
