VALUES ('f5bdc291-113e-52e1-a2fa-5508425d8a14', '65bff59a-5f58-5b72-93aa-0a091aa8a6e9', '2934b124-8578-59ea-a7c6-e71ce6138a4c', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Effective At', 'Date and time from which the exchange rate is applicable under its rate policy. Used to select the correct rate for a transaction, settlement, or accounting event. A rate without an effective time cannot be reliably reproduced when rates change over time. Supports deterministic selection and audit of the rate used by PaymentAllocation and accounting conversion. Required for temporal validity. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
