-- --------------------------------------------------------------------------
-- Bill Of Material (bus_bill_of_material)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c12a1b4-ce58-5623-a6f7-76a2906e9816', 'Bill Of Material', 'Maintain Bill Of Material records', 'Create, find and maintain Bill Of Material records. The list shows every Bill Of Material you have access to — select a row to open it, or use New to add one. Each row is a single Bill Of Material, described by 6 fields.

Id and Code are unique: no two Bill Of Material records may share the same value, and a save that would duplicate one is rejected. Code, Status and Product must be filled in before the record can be saved.

Every Bill Of Material points at Product. Choose the linked record from the lookup on those fields rather than typing an identifier. BOM Component and Manufacturing Work Order refer back to Bill Of Material, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Bill Of Material then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Bill Of Material with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('15d443c9-ff30-5dae-aa64-d87d59a8eb68', 'bus_bill_of_material', 'Bill Of Material', 'Represents a manufacturing master entity called BillOfMaterial within the CEDM business model. BillOfMaterial is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate BillOfMaterial records. The entity participates in a wider business graph through relationships with Product, BOMComponent. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical BillOfMaterial record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '7c12a1b4-ce58-5623-a6f7-76a2906e9816', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c407ba5d-e250-5db5-9637-912d4fa7b170', '7c12a1b4-ce58-5623-a6f7-76a2906e9816', '15d443c9-ff30-5dae-aa64-d87d59a8eb68', 'Bill Of Material', 'Shows one Bill Of Material at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('13c27ede-74e3-5af9-8233-90192bc01050', '15d443c9-ff30-5dae-aa64-d87d59a8eb68', 'id', 'Id', 'Identifies the bill of material record associated with this BillOfMaterial. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating BillOfMaterial records, where applicable. Its meaning is specific to BillOfMaterial; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dd6ac5d5-7055-5a92-8b04-e41c3b95d172', '15d443c9-ff30-5dae-aa64-d87d59a8eb68', 'code', 'Code', 'A human-readable business code used to identify or reference the record in operational processes and integrations. Used when creating, reviewing, searching, validating, reporting on, or integrating BillOfMaterial records, where applicable. Its meaning is specific to BillOfMaterial; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d903e13b-82f3-57f3-a475-dafca65f1547', '15d443c9-ff30-5dae-aa64-d87d59a8eb68', 'status', 'Status', 'The lifecycle state of the record. It controls which business actions are normally permitted and how the record is treated by related processes. Used when creating, reviewing, searching, validating, reporting on, or integrating BillOfMaterial records, where applicable. Its meaning is specific to BillOfMaterial; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the draft state or classification in the context of BillOfMaterial. Represents the active state or classification in the context of BillOfMaterial. Represents the obsolete state or classification in the context of BillOfMaterial. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1002, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
