-- --------------------------------------------------------------------------
-- Routing (bus_routing)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4172e42e-8338-59ca-afc3-7d0e5f375c72', 'Routing', 'Maintain Routing records', 'Create, find and maintain Routing records. The list shows every Routing you have access to — select a row to open it, or use New to add one. Each row is a single Routing, described by 4 fields.

Id is unique: no two Routing records may share the same value, and a save that would duplicate one is rejected. Code, Status and Product must be filled in before the record can be saved.

Every Routing points at Product. Choose the linked record from the lookup on those fields rather than typing an identifier. Operation and Manufacturing Work Order refer back to Routing, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Routing then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Routing with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c7423991-12f7-593c-a9af-cafe334924ee', 'bus_routing', 'Routing', 'Versioned definition of manufacturing process sequence. BillOfMaterial defines what materials are required; Routing defines how the output is produced. MRP, scheduling, costing, shop-floor execution, quality, and traceability. Product is the output; Operations define steps; WorkCenters provide capacity; ManufacturingWorkOrder executes a selected version. Draft → active → suspended/obsolete with versioned replacement. Routing changes revalidate planned/unreleased work; released/completed work retains historical version.', 'A', FALSE, FALSE, FALSE, TRUE, '4172e42e-8338-59ca-afc3-7d0e5f375c72', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('54f15f0f-37cd-530a-b0a6-dfab0dd7b361', '4172e42e-8338-59ca-afc3-7d0e5f375c72', 'c7423991-12f7-593c-a9af-cafe334924ee', 'Routing', 'Shows one Routing at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
