VALUES ('89240f8b-e4cc-5ce7-bf62-c67f62ed9e0b', 'c7423991-12f7-593c-a9af-cafe334924ee', 'status', 'Status', 'Governance state of routing. Controls eligibility for new production release. Engineering change and manufacturing control. Historical orders retain prior routing evidence. Being prepared. Eligible for production. Temporarily blocked. Superseded for new use. Required.', 1028, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
