-- --------------------------------------------------------------------------
-- Work Center (bus_work_center)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f250b5e8-e407-5684-9dcf-0ca89e20fb8b', 'Work Center', 'Maintain Work Center records', 'Create, find and maintain Work Center records. The list shows every Work Center you have access to — select a row to open it, or use New to add one. Each row is a single Work Center, described by 6 fields.

Id and Code are unique: no two Work Center records may share the same value, and a save that would duplicate one is rejected. Code, Name and Status must be filled in before the record can be saved.

Every Work Center points at Location. Choose the linked record from the lookup on those fields rather than typing an identifier. Operation refers back to Work Center, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Work Center then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Work Center with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('926a49fb-750c-5718-b6cc-387c2ab630b9', 'bus_work_center', 'Work Center', 'Manufacturing capacity resource used by routing and execution. WorkCenter represents where or by which resource an Operation is performed. Manufacturing planning, scheduling, dispatch, costing, maintenance coordination, and analytics. Operation defines work; Routing sequences work; ManufacturingWorkOrder executes it. Active → temporarily unavailable/maintenance → active or retired. Capacity/status changes revalidate affected schedules and unreleased work without rewriting completed execution.', 'A', FALSE, FALSE, FALSE, TRUE, 'f250b5e8-e407-5684-9dcf-0ca89e20fb8b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
