-- --------------------------------------------------------------------------
-- Manufacturing Work Order (bus_manufacturing_work_order)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('138696b1-ba26-5f0b-bf58-477636f423dd', 'Manufacturing Work Order', 'Maintain Manufacturing Work Order records', 'Create, find and maintain Manufacturing Work Order records. The list shows every Manufacturing Work Order you have access to — select a row to open it, or use New to add one. Each row is a single Manufacturing Work Order, described by 10 fields.

Id and Order Number are unique: no two Manufacturing Work Order records may share the same value, and a save that would duplicate one is rejected. Order Number, Quantity, Status and Product must be filled in before the record can be saved.

Every Manufacturing Work Order points at Product, Location, Bill Of Material and Routing. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Manufacturing Work Order then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Manufacturing Work Order with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('da44c725-f1d6-5212-8326-03e2a61d6621', 'bus_manufacturing_work_order', 'Manufacturing Work Order', 'Canonical CEDM production-order transaction. ManufacturingWorkOrder authorizes production; BOM defines material expectations; Routing defines process expectations; execution transactions preserve actual material, output and scrap evidence. MRP, scheduling, shop-floor execution, inventory, costing, quality, genealogy and project manufacturing. Product is output; BOM and Routing are controlled definitions; MaterialIssue consumes inputs; ProductionReceipt accepts outputs; Scrap explains governed losses. Planned → released → in progress → completed → closed, with controlled cancellation. Release freezes effective definitions; execution updates inventory and genealogy; corrections use compensating evidence rather than rewriting posted history.', 'A', FALSE, FALSE, FALSE, TRUE, '138696b1-ba26-5f0b-bf58-477636f423dd', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2f017840-7f2a-56a5-8d54-c4304393ef75', '138696b1-ba26-5f0b-bf58-477636f423dd', 'da44c725-f1d6-5212-8326-03e2a61d6621', 'Manufacturing Work Order', 'Shows one Manufacturing Work Order at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product, Location, Bill Of Material and Routing are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
