VALUES ('edf62659-9fe0-5385-ae03-e9cf62b5ec28', '2f017840-7f2a-56a5-8d54-c4304393ef75', '517f57fc-c4a5-56d0-970d-46fb190b751a', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Order Number', 'Human-facing production-order reference. Operational identifier used across planning and shop-floor execution. Scheduling, material staging, production, quality, costing, and audit. Distinct from inventory transaction references. Required. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Manufacturing Work Order already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
