VALUES ('bd62ffb0-680d-5b1b-8938-a5a03ae34614', '2f017840-7f2a-56a5-8d54-c4304393ef75', '1216f30f-a4e3-50c3-aa43-67e2ed4d60c2', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Status', 'Manufacturing order lifecycle state. Controls authorization and execution eligibility. Planning, shop-floor control, inventory and costing. Posted execution evidence is not reversed by changing header status. Being planned and not executable. Authorized for governed execution. Execution has begun. Production execution is materially complete pending closure where applicable. Reconciled and administratively closed. Terminated before remaining execution. Required. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
