VALUES ('eb9a82d5-248d-561a-a0b8-8bc1d1a354cd', 'bf332dce-24f3-509c-909a-0daca5b4344b', 'ff9d6565-f969-5a79-96d2-e91de1ff63b0', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Lot', 'Output production lot. Groups produced quantity for genealogy/quality/recall. Traceability and quality release. Required according to lot-control policy. May remain quarantined pending required quality evidence.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
