VALUES ('f4ffeddc-40f6-58d3-936b-b759742e0a9e', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'expires_at', 'Expires At', 'Expiry or use-by time for the lot. Controls eligibility where shelf life applies. FEFO allocation, quarantine, disposal, and compliance. Does not itself post inventory movement. Optional for non-expiring products.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
