-- --------------------------------------------------------------------------
-- Serial Number (bus_serial_number)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1250fa9b-e8c6-5f15-959e-c8d61e7f0ea9', 'Serial Number', 'Maintain Serial Number records', 'Create, find and maintain Serial Number records. The list shows every Serial Number you have access to — select a row to open it, or use New to add one. Each row is a single Serial Number, described by 8 fields.

Id is unique: no two Serial Number records may share the same value, and a save that would duplicate one is rejected. Serial Code, Status and Product must be filled in before the record can be saved.

Every Serial Number points at Product, Material Issue, Production Receipt, Lot and Scrap. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Serial Number then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Serial Number with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6fae4cfd-72f3-53d1-b819-acf129f8c9f6', 'bus_serial_number', 'Serial Number', 'Unit-level identity and custody traceability for serialized products. Product identifies the type, Lot identifies a batch, and SerialNumber identifies one physical unit. Inventory, warehouse, logistics, manufacturing, service, maintenance, warranty, returns, recall, and asset management. SerialNumber travels through InventoryMovement and may be associated with a Lot while preserving unique unit identity. Expected → available/reserved → in transit/installed/consumed/returned/quarantined → scrapped/retired as applicable. Status and custody changes revalidate inventory, reservation, shipment, service, return, and asset workflows; historical custody is never rewritten.', 'A', FALSE, FALSE, FALSE, TRUE, '1250fa9b-e8c6-5f15-959e-c8d61e7f0ea9', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6b5d6ce0-1d0d-5e19-859f-ac401e8d9ef8', '1250fa9b-e8c6-5f15-959e-c8d61e7f0ea9', '6fae4cfd-72f3-53d1-b819-acf129f8c9f6', 'Serial Number', 'Shows one Serial Number at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product, Material Issue, Production Receipt, Lot and Scrap are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
