INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b0950114-d3bc-5040-9c25-e4b8c38e84c2', '721e267a-ad30-56a9-9db6-21fda8e07198', 'fdc0fec9-5865-59df-8b5b-e9cc66089964', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Id', 'Immutable identity of the inventory event. Used for stock-ledger traceability, audit, reconciliation, integration and investigation. Identifies the event independently of Product, location, quantity and originating transaction. Every receipt, issue, transfer, return, adjustment, reservation and release uses this identity for audit and balance reconciliation. Required. Must be unique: a save is rejected if another Inventory Movement already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
