VALUES ('bef095b0-9a54-55fd-bf55-9c38ddb2c193', '1104c267-0bf1-5094-9ecd-5780506faa81', 'f411427c-4090-58c5-8241-0d837c48fc86', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Id', 'Identifies the production record record associated with this ProductionRecord. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating ProductionRecord records, where applicable. Its meaning is specific to ProductionRecord; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value. Must be unique: a save is rejected if another Production Record already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
