INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a2cb56e5-1714-5026-9b0b-56f3a3c78217', 'Scrap', 'Maintain Scrap records', 'Create, find and maintain Scrap records. The list shows every Scrap you have access to — select a row to open it, or use New to add one. Each row is a single Scrap, described by 8 fields.

Id and Scrap Number are unique: no two Scrap records may share the same value, and a save that would duplicate one is rejected. Scrap Number, Quantity, Reason Code, Scrapped At, Work Order and Product must be filled in before the record can be saved.

Every Scrap points at Product and Lot. Choose the linked record from the lookup on those fields rather than typing an identifier. Serial Number and Inventory Movement refer back to Scrap, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Scrap then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Scrap with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b74eb956-5a6f-5474-aa1d-78a0b478dd21', 'bus_scrap', 'Scrap', 'Governed manufacturing loss/disposition evidence. Scrap explains rejected or lost quantity; it is distinct from accepted ProductionReceipt and from InventoryMovement, which remains the stock ledger. Yield, manufacturing variance, quality, costing, genealogy, inventory and continuous improvement. ManufacturingWorkOrder supplies context; Nonconformance may explain quality cause; Lot/Serial preserve genealogy; InventoryMovement records stock consequence when applicable. Recorded → validated/authorized → inventory/quality reconciled → immutable historical evidence. Scrap updates yield/cost/quality analysis and inventory only through governed attributable transactions.', 'A', FALSE, FALSE, FALSE, TRUE, 'a2cb56e5-1714-5026-9b0b-56f3a3c78217', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('85ea5b94-1e91-59f6-be65-caf1b822cdfa', 'a2cb56e5-1714-5026-9b0b-56f3a3c78217', 'b74eb956-5a6f-5474-aa1d-78a0b478dd21', 'Scrap', 'Shows one Scrap at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product and Lot are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
