INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b1ed941b-1847-5bd7-ab4a-73fe6143e3d9', 'b74eb956-5a6f-5474-aa1d-78a0b478dd21', 'scrapped_at', 'Scrapped At', 'Effective scrap time. Establishes production-loss chronology. Cost period, genealogy and audit. Must align with related execution evidence. Required.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
