INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cbb5efdf-52e5-5d31-bfc6-bd32ea9908f8', 'b74eb956-5a6f-5474-aa1d-78a0b478dd21', 'work_order_id', 'Work Order', 'Production order under which scrap occurred. Supplies production authorization and planned context. Yield and variance reconciliation. Exactly one work order. Scrap contributes to completion reconciliation.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
