INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('96186c35-8f7c-5aed-bbb9-6e8ea947fef2', 'b74eb956-5a6f-5474-aa1d-78a0b478dd21', 'product_id', 'Product', 'Material or output being scrapped. Identifies the item affected. Inventory, costing, quality and analysis. Exactly one Product. Must reconcile with work-order input/output context or approved exception.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
