VALUES ('69e12cfb-f6a4-5842-9c81-d5aae0939fa5', '85ea5b94-1e91-59f6-be65-caf1b822cdfa', '56c12d4a-f7dd-5987-bd72-8ff07740408f', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Reason Code', 'Governed reason for scrap. Classifies why material/output was lost or rejected. Quality analysis, costing and continuous improvement. Should align with controlled reason taxonomy. Required. Required — the record cannot be saved while this is empty. Up to 100 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
