VALUES ('be3501a8-9495-5edb-8ceb-5cadd0392947', '85ea5b94-1e91-59f6-be65-caf1b822cdfa', 'b1ed941b-1847-5bd7-ab4a-73fe6143e3d9', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Scrapped At', 'Effective scrap time. Establishes production-loss chronology. Cost period, genealogy and audit. Must align with related execution evidence. Required. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
