INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2d332bf8-cb3c-5c39-be07-e8f13cfef375', '85ea5b94-1e91-59f6-be65-caf1b822cdfa', 'cbb5efdf-52e5-5d31-bfc6-bd32ea9908f8', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Work Order', 'Production order under which scrap occurred. Supplies production authorization and planned context. Yield and variance reconciliation. Exactly one work order. Scrap contributes to completion reconciliation. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
