INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c52180b1-b512-5c69-a42a-020f8aa40288', 'bus_bom_component', 'BOM Component', 'Represents a manufacturing detail entity called BOMComponent within the CEDM business model. BOMComponent is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate BOMComponent records. The entity participates in a wider business graph through relationships with BillOfMaterial, Product. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical BOMComponent record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '7c12a1b4-ce58-5623-a6f7-76a2906e9816', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e16380a3-5d96-5716-9816-5bc955338dcc', '7c12a1b4-ce58-5623-a6f7-76a2906e9816', 'c52180b1-b512-5c69-a42a-020f8aa40288', 'BOM Component', 'Shows one BOM Component at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Bill Of Material is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
