VALUES ('ee05bf12-ce2e-5af6-9f8a-9c1c408a5d6a', 'c52180b1-b512-5c69-a42a-020f8aa40288', 'id', 'Id', 'Identifies the bom component record associated with this BOMComponent. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating BOMComponent records, where applicable. Its meaning is specific to BOMComponent; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
