INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f9b8d51a-c348-5b53-b26d-de297d5e4463', 'bus_operation', 'Operation', 'Standard process step within a manufacturing routing. Defines work to perform, while ManufacturingWorkOrder records production authorization/execution. Routing, scheduling, costing, shop-floor instructions, and in-process quality. Routing sequences operations; WorkCenter provides capacity; QualityPlan governs inspection. Governed by parent routing version; historical released work retains its definition snapshot/reference. Definition/resource/quality changes affect future or unreleased work and trigger impact analysis for active work.', 'A', FALSE, FALSE, FALSE, TRUE, '4172e42e-8338-59ca-afc3-7d0e5f375c72', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
