VALUES ('0306f303-af93-5c87-ad10-c173218bcf81', 'bus_product_lifecycle', 'Product Lifecycle', 'Effective-dated audit trail of product eligibility changes. Product.status is current state; ProductLifecycle preserves governed transition history and reason. PIM governance, product introduction, blocking, discontinuation and retirement. Changes propagate to open dependent workflows while historical evidence remains immutable. Append-only governed transition history for Product.', 'A', FALSE, FALSE, FALSE, TRUE, '7dba018c-7907-5026-a588-ed49e0837f7c', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
